window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5f8b01a17ab20d1c"]={"versions": [{"id": "FIG-5f8b01a17ab20d1c", "releases": ["R1.3.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout (Protokoll-Header-Diagramm) zur Spezifikation des Headers für das AUTOSAR End-to-End (E2E) Kommunikationsprofil 7 (Profile 7). Es veranschaulicht die serielle Anordnung der Protokollkontrollfelder innerhalb der übertragenen Dateneinheit über einer 32-Bit-Rasterung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 160-Bit (20 Byte) umfassende Header-Struktur mit folgenden Feldern:</p>\n<ul class=\"fig-list\"><li>Spaltenraster / Header-Achsen: Obere Byte-Zählung (0, 1, 2, 3) und Bit-Ebene (0 bis 31), indiziert mit „Transmission order“.\n</li><li>Byte-Offset-Achse: Zeilenweise Offsets 0, 4, 8, 12, 16.\n</li><li>E2E CRC: 64-Bit-Prüfsumme (Offset 0 und 4, Bytes 0 bis 7).\n</li><li>E2E Length: 32-Bit-Längenangabe (Offset 8, Bytes 8 bis 11).\n</li><li>E2E Counter: 32-Bit-Sequenzzähler (Offset 12, Bytes 12 bis 15).\n</li><li>E2E Data ID: 32-Bit-Identifikator der Daten (Offset 16, Bytes 16 bis 19).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikation des Serialisierungsformats:</p>\n<ul class=\"fig-list\"><li>Die Übertragung erfolgt gemäß „Transmission order“ beginnend bei Bit 0 und Byte 0.\n</li><li>Senderseitig werden Zähler (Counter) inkrementiert, die Länge ermittelt, die Data ID eingebunden und die CRC über Nutzdaten und Steuerfelder berechnet.\n</li><li>Empfängerseitig werden die Felder in derselben Reihenfolge deserialisiert, um Integrität (CRC), Aktualität (Counter) und Datenzuordnung (Data ID) nach E2E Profile 7 zu validieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Bit- und Byte-Alignment für Implementierungen von E2E Profile 7:</p>\n<ul class=\"fig-list\"><li>Gesamtlänge des Headers beträgt exakt 20 Byte (160 Bit).\n</li><li>64-Bit-Feld für E2E CRC (CRC-64) und jeweils 32-Bit-Felder für Length, Counter und Data ID.\n</li><li>Die Ausrichtung erfolgt an 32-Bit-Wortgrenzen in Big-Endian- bzw. nativer E2E-Profil-7-Bytereihenfolge gemäß den definierten Byte- und Bit-Offsets.\n</li></ul>"}, {"id": "FIG-8ec889a9d53aae89", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout (Protokoll-Header-Diagramm) zur Spezifikation des Headers für das AUTOSAR End-to-End (E2E) Kommunikationsprofil 7 (Profile 7). Es veranschaulicht die serielle Anordnung der Protokollkontrollfelder innerhalb der übertragenen Dateneinheit über einer 32-Bit-Rasterung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 160-Bit (20 Byte) umfassende Header-Struktur mit folgenden Feldern:</p>\n<ul class=\"fig-list\"><li>Spaltenraster / Header-Achsen: Obere Byte-Zählung (0, 1, 2, 3) und Bit-Ebene (0 bis 31), indiziert mit „Transmission order“.\n</li><li>Byte-Offset-Achse: Zeilenweise Offsets 0, 4, 8, 12, 16.\n</li><li>E2E CRC: 64-Bit-Prüfsumme (Offset 0 und 4, Bytes 0 bis 7).\n</li><li>E2E Length: 32-Bit-Längenangabe (Offset 8, Bytes 8 bis 11).\n</li><li>E2E Counter: 32-Bit-Sequenzzähler (Offset 12, Bytes 12 bis 15).\n</li><li>E2E Data ID: 32-Bit-Identifikator der Daten (Offset 16, Bytes 16 bis 19).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikation des Serialisierungsformats:</p>\n<ul class=\"fig-list\"><li>Die Übertragung erfolgt gemäß „Transmission order“ beginnend bei Bit 0 und Byte 0.\n</li><li>Senderseitig werden Zähler (Counter) inkrementiert, die Länge ermittelt, die Data ID eingebunden und die CRC über Nutzdaten und Steuerfelder berechnet.\n</li><li>Empfängerseitig werden die Felder in derselben Reihenfolge deserialisiert, um Integrität (CRC), Aktualität (Counter) und Datenzuordnung (Data ID) nach E2E Profile 7 zu validieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Bit- und Byte-Alignment für Implementierungen von E2E Profile 7:</p>\n<ul class=\"fig-list\"><li>Gesamtlänge des Headers beträgt exakt 20 Byte (160 Bit).\n</li><li>64-Bit-Feld für E2E CRC (CRC-64) und jeweils 32-Bit-Felder für Length, Counter und Data ID.\n</li><li>Die Ausrichtung erfolgt an 32-Bit-Wortgrenzen in Big-Endian- bzw. nativer E2E-Profil-7-Bytereihenfolge gemäß den definierten Byte- und Bit-Offsets.\n</li></ul>"}, {"id": "FIG-253be7a1e0429c9a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout (Protokoll-Header-Diagramm) zur Spezifikation des Headers für das AUTOSAR End-to-End (E2E) Kommunikationsprofil 7 (Profile 7). Es veranschaulicht die serielle Anordnung der Protokollkontrollfelder innerhalb der übertragenen Dateneinheit über einer 32-Bit-Rasterung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 160-Bit (20 Byte) umfassende Header-Struktur mit folgenden Feldern:</p>\n<ul class=\"fig-list\"><li>Spaltenraster / Header-Achsen: Obere Byte-Zählung (0, 1, 2, 3) und Bit-Ebene (0 bis 31), indiziert mit „Transmission order“.\n</li><li>Byte-Offset-Achse: Zeilenweise Offsets 0, 4, 8, 12, 16.\n</li><li>E2E CRC: 64-Bit-Prüfsumme (Offset 0 und 4, Bytes 0 bis 7).\n</li><li>E2E Length: 32-Bit-Längenangabe (Offset 8, Bytes 8 bis 11).\n</li><li>E2E Counter: 32-Bit-Sequenzzähler (Offset 12, Bytes 12 bis 15).\n</li><li>E2E Data ID: 32-Bit-Identifikator der Daten (Offset 16, Bytes 16 bis 19).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikation des Serialisierungsformats:</p>\n<ul class=\"fig-list\"><li>Die Übertragung erfolgt gemäß „Transmission order“ beginnend bei Bit 0 und Byte 0.\n</li><li>Senderseitig werden Zähler (Counter) inkrementiert, die Länge ermittelt, die Data ID eingebunden und die CRC über Nutzdaten und Steuerfelder berechnet.\n</li><li>Empfängerseitig werden die Felder in derselben Reihenfolge deserialisiert, um Integrität (CRC), Aktualität (Counter) und Datenzuordnung (Data ID) nach E2E Profile 7 zu validieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindendes Bit- und Byte-Alignment für Implementierungen von E2E Profile 7:</p>\n<ul class=\"fig-list\"><li>Gesamtlänge des Headers beträgt exakt 20 Byte (160 Bit).\n</li><li>64-Bit-Feld für E2E CRC (CRC-64) und jeweils 32-Bit-Felder für Length, Counter und Data ID.\n</li><li>Die Ausrichtung erfolgt an 32-Bit-Wortgrenzen in Big-Endian- bzw. nativer E2E-Profil-7-Bytereihenfolge gemäß den definierten Byte- und Bit-Offsets.\n</li></ul>"}], "trans": [{"from": "FIG-5f8b01a17ab20d1c", "to": "FIG-8ec889a9d53aae89", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8ec889a9d53aae89", "to": "FIG-5f8b01a17ab20d1c", "fr": "R1.5.1", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5f8b01a17ab20d1c", "to": "FIG-253be7a1e0429c9a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
